import restatements from "./fixtures/restatements.json";
import type { RestatementDiff } from "./types";

const DIFFS = restatements as RestatementDiff[];

/**
 * The restatement console: one card per restated fact, one row per economic field, naming
 * every field the backend's `RestatementDiff.of` compared. `fixtures/restatements.json` is
 * generated by `ConsoleFixtureExporterTest` (part of the Java/Kotlin repo's default test
 * run), not hand-typed, so this view always reflects something the backend actually
 * computed.
 */
export function App() {
  return (
    <main>
      <h1>Book of Record: Restatement Console</h1>
      <p>
        Every row below names the field the correction changed (or left unchanged) between
        the superseded version and the version that replaced it, plus the as-of timestamp
        the correction took effect.
      </p>
      {DIFFS.map((diff) => (
        <RestatementCard key={diff.factId} diff={diff} />
      ))}
    </main>
  );
}

function RestatementCard({ diff }: { diff: RestatementDiff }) {
  return (
    <section data-testid={`restatement-${diff.factId}`}>
      <h2>
        {diff.symbol} &mdash; account {diff.accountId} &mdash; fact {diff.factId}
      </h2>
      <p>
        Effective date {diff.effectiveDate}. Restated at {diff.restatedAsOfFrom} (prior
        version was current from {diff.priorAsOfFrom}).
      </p>
      <table>
        <thead>
          <tr>
            <th>Field</th>
            <th>Prior value</th>
            <th>Restated value</th>
            <th>Changed</th>
          </tr>
        </thead>
        <tbody>
          {diff.fields.map((field) => (
            <tr key={field.fieldName} data-testid={`field-${diff.factId}-${field.fieldName}`}>
              <td>{field.fieldName}</td>
              <td>{field.priorValue}</td>
              <td>{field.restatedValue}</td>
              <td>{field.changed ? "yes" : "no"}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}
